// Firebase configuration for DiaCare.
//
// Normally generated by `flutterfire configure`. Written by hand from the
// values the Firebase CLI reports, because flutterfire configure needs an
// interactive browser session and these are the same values it would have
// produced:
//
//   firebase apps:sdkconfig ANDROID 1:2509170380:android:e1429744c082d80614c469
//   firebase apps:sdkconfig WEB     1:2509170380:web:f8accd3656bcca1f14c469
//
// These identify the project; they authorize nothing on their own. What
// protects the data is firestore.rules plus the claims a BHW only gets by
// signing in through /api/bhw-login. Regenerate with the commands above if
// an app is ever recreated in the console.

import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show defaultTargetPlatform, kIsWeb, TargetPlatform;

class DefaultFirebaseOptions {
  static FirebaseOptions get currentPlatform {
    if (kIsWeb) return web;

    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      case TargetPlatform.iOS:
      case TargetPlatform.macOS:
        // No iOS app is registered in the project yet. Failing here with a
        // clear reason beats failing later inside the Firebase SDK with
        // something that reads like a bug in the app.
        throw UnsupportedError(
          'DiaCare has no iOS app registered in Firebase yet. Run:\n'
          '  firebase apps:create IOS "DiaCare BHW App" --bundle-id <bundle id>\n'
          'then add the values here.',
        );
      default:
        throw UnsupportedError(
          'DiaCare is not configured for $defaultTargetPlatform.',
        );
    }
  }

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'AIzaSyDFU0KsEn7_5BQ6hosHesaZBKBoGQiPwEo',
    appId: '1:2509170380:android:e1429744c082d80614c469',
    messagingSenderId: '2509170380',
    projectId: 'diacare-fe2d1',
    storageBucket: 'diacare-fe2d1.firebasestorage.app',
  );

  static const FirebaseOptions web = FirebaseOptions(
    apiKey: 'AIzaSyCrTy4ZepaRiVj4nYwlTqUQWXhqCy4g9JQ',
    appId: '1:2509170380:web:f8accd3656bcca1f14c469',
    messagingSenderId: '2509170380',
    projectId: 'diacare-fe2d1',
    authDomain: 'diacare-fe2d1.firebaseapp.com',
    storageBucket: 'diacare-fe2d1.firebasestorage.app',
    measurementId: 'G-VZ1L39Q6KW',
  );
}
